#!/data/data/com.termux/files/usr/bin/bash
set -euo pipefail

# 소르베 서버 모듈 설치 (안드로이드 · Termux)
# 마리나라를 끄고, 이 파일을 Marinara-Engine 최상위 폴더에 넣은 뒤:
#   bash ./INSTALL_SORBET_SERVER_TERMUX.sh
# 이 파일은 build-installers.mjs 가 만든다. 손으로 고치지 않는다.

ROOT="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)"
export SORBET_ENGINE_ROOT="$ROOT"

echo
echo "[소르베] 서버 모듈 설치를 시작합니다."
echo "[중요] 실행 중인 마리나라를 완전히 끈 상태에서 실행하세요."
echo

if [ ! -f "$ROOT/package.json" ] || [ ! -f "$ROOT/packages/server/src/routes/index.ts" ] || [ ! -f "$ROOT/packages/server/src/routes/backup.routes.ts" ]; then
  echo "[실패] 이 파일을 Marinara-Engine 최상위 폴더에 넣은 뒤 실행하세요." >&2
  exit 1
fi
if [ ! -f "$ROOT/start-termux.sh" ]; then
  echo "[실패] start-termux.sh 가 없습니다. 안드로이드(Termux)용 마리나라 폴더인지 확인하세요." >&2
  exit 1
fi

node <<'NODE'
const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(process.env.SORBET_ENGINE_ROOT);
const server = path.join(root, "packages/server/src");
const FILES = [
  ["routes/sorbet.routes.ts", ""],
  ["services/storage/sorbet.storage.ts", ""],
  ["routes/sorbet-runs.routes.ts", ""],
  ["services/storage/sorbet-runs.storage.ts", ""],
];
const IMPORTS = ["import { sorbetRoutes } from \"./sorbet.routes.js\";","import { sorbetRunsRoutes } from \"./sorbet-runs.routes.js\";"];
const REGISTERS = ["  await app.register(sorbetRoutes, { prefix: \"/api/sorbet\" });","  await app.register(sorbetRunsRoutes, { prefix: \"/api/sorbet-runs\" });"];

const indexPath = path.join(server, "routes/index.ts");
const backupPath = path.join(server, "routes/backup.routes.ts");
let indexText = fs.readFileSync(indexPath, "utf8");
let backupText = fs.readFileSync(backupPath, "utf8");
const nl = (t) => (t.includes("\r\n") ? "\r\n" : "\n");

const head = "export async function registerRoutes";
const missingImports = IMPORTS.filter((l) => !indexText.includes(l));
if (missingImports.length) {
  const at = indexText.indexOf(head);
  if (at < 0) throw new Error("routes/index.ts 에서 registerRoutes 를 찾지 못했습니다. 엔진 버전을 확인하세요.");
  indexText = indexText.slice(0, at) + missingImports.join(nl(indexText)) + nl(indexText) + nl(indexText) + indexText.slice(at);
}
const body = "export async function registerRoutes(app: FastifyInstance) {";
const missingRegs = REGISTERS.filter((l) => !indexText.includes(l.trim()));
if (missingRegs.length) {
  const markerAt = indexText.indexOf(body);
  if (markerAt < 0) throw new Error("routes/index.ts 의 등록 위치를 찾지 못했습니다. 엔진 버전을 확인하세요.");
  const at = markerAt + body.length;
  indexText = indexText.slice(0, at) + missingRegs.map((l) => nl(indexText) + l).join("") + indexText.slice(at);
}
if (!backupText.includes('"sorbet"')) {
  const marker = "const BACKUP_DIRS = [";
  const markerAt = backupText.indexOf(marker);
  if (markerAt < 0) throw new Error("backup.routes.ts 에서 BACKUP_DIRS 를 찾지 못했습니다. 엔진 버전을 확인하세요.");
  const at = markerAt + marker.length;
  backupText = backupText.slice(0, at) + nl(backupText) + '  "sorbet",' + backupText.slice(at);
}

for (const [rel, b64] of FILES) {
  const target = path.join(server, rel);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, Buffer.from(b64, "base64"));
}
fs.writeFileSync(indexPath, indexText, "utf8");
fs.writeFileSync(backupPath, backupText, "utf8");

// 런처는 서버 빌드가 없을 때만 다시 빌드한다 — 지워서 새 모듈이 빌드되게 한다
fs.rmSync(path.join(root, "packages/server/dist"), { recursive: true, force: true });
console.log("[완료] 서버 파일 4개, 라우트 연결, 백업 폴더 등록을 마쳤습니다.");
NODE

echo
echo "설치가 끝났습니다. 마리나라를 다시 빌드하고 켭니다."
echo
exec bash "$ROOT/start-termux.sh" --skip-update
